// Ref: #/components/schemas/Job
type Job struct {
	// Stable public identifier. The freehire page is https://freehire.me/jobs/{public_slug}.
	PublicSlug  string    `json:"public_slug"`
	Title       string    `json:"title"`
	Company     string    `json:"company"`
	CompanySlug OptString `json:"company_slug"`
	// The employer's own application URL. This is where an applicant goes.
	URL OptURI `json:"url"`
	// The posting's own location string, verbatim and unnormalized. Filter on the geography facets
	// instead.
	Location OptString `json:"location"`
	// Origin slug — the ATS or board this posting was crawled from.
	Source OptString `json:"source"`
	// The source's own identifier for the posting.
	ExternalID OptString `json:"external_id"`
	// True for a hand-curated posting rather than an automated crawl.
	ManuallyAdded OptBool `json:"manually_added"`
	// Stored verbatim HTML by default. `searchJobs` serves a truncated preview; `agentSearchJobs` and
	// `getJob` serve the full body, and `agentSearchJobs` can convert it via `description_format`.
	Description OptString `json:"description"`
	Regions     []string  `json:"regions"`
	Countries   []string  `json:"countries"`
	Cities      []string  `json:"cities"`
	// Absent when the posting's format could not be resolved.
	WorkMode OptJobWorkMode `json:"work_mode"`
	Skills   []string       `json:"skills"`
	// Curated collection slugs of the posting's company.
	Collections []string `json:"collections"`
	// Absent when unknown.
	IsTech   OptJobIsTech   `json:"is_tech"`
	PostedAt OptNilDateTime `json:"posted_at"`
	// When freehire first saw the posting.
	CreatedAt OptNilDateTime `json:"created_at"`
	UpdatedAt OptNilDateTime `json:"updated_at"`
	// When a re-crawl last confirmed the posting was still live.
	LastSeenAt OptNilDateTime `json:"last_seen_at"`
	// Non-null once the posting is no longer open. Only `getJob` ever serves such a row.
	ClosedAt   OptNilDateTime `json:"closed_at"`
	Enrichment OptEnrichment  `json:"enrichment"`
	EnrichedAt OptNilDateTime `json:"enriched_at"`
	// Bumped when the enrichment contract changes — use it to detect re-enriched rows.
	EnrichmentVersion OptNilInt `json:"enrichment_version"`
	// The calling user's vote. Always null on this unauthenticated schema.
	MyVote          OptNilInt   `json:"my_vote"`
	Reality         OptReality  `json:"reality"`
	Ghost           OptNilGhost `json:"ghost"`
	ViewCount       OptInt      `json:"view_count"`
	AppliedCount    OptInt      `json:"applied_count"`
	UpvoteCount     OptInt      `json:"upvote_count"`
	DownvoteCount   OptInt      `json:"downvote_count"`
	AdditionalProps JobAdditional
}

